1: import { createHash } from 'node:crypto';
2: import { constants } from 'node:fs';
3: import { lstat, mkdir, open, realpath, rmdir } from 'node:fs/promises';
4: import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
5: import { RepositoryReader, runAudit, type Finding, type Report } from './engine.ts';
6: 
7: /** Only explicitly registered, fixed-content files may be created. */
8: const FIXES = Object.freeze([
9:   {
10:     ruleId: 'repo.pr-template',
11:     path: '.github/pull_request_template.md',
12:     reason: 'Add a small PR template for motivation, changes, and verification.',
13:     content: `## Summary\n\n<!-- What changed? -->\n\n## Motivation\n\n<!-- Why is this needed? -->\n\n## Testing\n\n<!-- Commands and results, or why tests were not run. -->\n\n## Related issues\n\n<!-- Closes #123 / Refs #123, when applicable. -->\n`,
14:   },
15:   {
16:     ruleId: 'dx.editorconfig',
17:     path: '.editorconfig',
18:     reason: 'Add basic portable editor conventions without choosing an indentation style.',
19:     content: `root = true\n\n[*]\ncharset = utf-8\nend_of_line = lf\ninsert_final_newline = true\n`,
20:   },
21: ] as const);
22: 
23: export type FixProposal = {
24:   ruleId: string;
25:   path: string;
26:   reason: string;
27:   content: string;
28:   diff: string;
29: };
30: export type FixPlan = {
31:   schemaVersion: '0.1';
32:   mode: 'remediate';
33:   planId: string;
34:   proposals: FixProposal[];
35: };
36: export type FixOutcome = {
37:   schemaVersion: '0.1';
38:   mode: 'apply';
39:   planId: string;
40:   changed: string[];
41:   verified: { ruleId: string; status: Finding['status'] }[];
42: };
43: 
44: export class RemediationError extends Error {
45:   constructor(message: string) { super(message); this.name = 'RemediationError'; }
46: }
47: 
48: function patchFor(path: string, content: string): string {
49:   const lines = content.endsWith('\n') ? content.slice(0, -1).split('\n') : content.split('\n');
50:   return [`--- /dev/null`, `+++ b/${path}`, `@@ -0,0 +1,${lines.length} @@`, ...lines.map((line) => `+${line}`)].join('\n') + '\n';
51: }
52: 
53: function planDigest(proposals: readonly FixProposal[]): string {
54:   const stable = proposals.map(({ ruleId, path, content }) => ({ ruleId, path, content }));
55:   return createHash('sha256').update(JSON.stringify(stable)).digest('hex');
56: }
57: 
58: function isMissing(finding: Finding | undefined): boolean {
59:   // These two rules currently only produce WARN/FAIL for a verified absent file.
60:   // Do not propose changes for UNKNOWN, heuristic findings, or disabled checks.
61:   return finding !== undefined && (finding.status === 'WARN' || finding.status === 'FAIL')
62:     && finding.confidence === 'verified';
63: }
64: 
65: export async function planRemediation(repositoryRoot = process.cwd()): Promise<FixPlan> {
66:   const root = await realpath(resolve(repositoryRoot));
67:   const report: Report = await runAudit(root);
68:   if (report.errors.length) throw new RemediationError('Audit reported execution errors; refusing to propose fixes');
69:   const reader = new RepositoryReader(root);
70:   const proposals: FixProposal[] = [];
71:   for (const fix of FIXES) {
72:     const finding = report.findings.find((item) => item.ruleId === fix.ruleId);
73:     if (!isMissing(finding)) continue;
74:     const target = await reader.probe(fix.path);
75:     if (target.kind !== 'missing') continue;
76:     proposals.push({ ruleId: fix.ruleId, path: fix.path, reason: fix.reason,
77:       content: fix.content, diff: patchFor(fix.path, fix.content) });
78:   }
79:   return { schemaVersion: '0.1', mode: 'remediate', planId: planDigest(proposals), proposals };
80: }
81: 
82: function safePath(root: string, filePath: string): string {
83:   const path = resolve(root, filePath);
84:   const remainder = relative(root, path);
85:   if (!remainder || isAbsolute(remainder) || remainder === '..' || remainder.startsWith('..' + sep)) {
86:     throw new RemediationError('Destination escapes the repository root');
87:   }
88:   return path;
89: }
90: 
91: async function inspectDestination(root: string, path: string): Promise<'absent' | 'directory-missing'> {
92:   const absolute = safePath(root, path);
93:   const parent = dirname(absolute);
94:   if (parent !== root) {
95:     const relativeParent = relative(root, parent);
96:     // Only one allowed nested destination: .github/pull_request_template.md.
97:     if (relativeParent !== '.github') throw new RemediationError('Unexpected destination directory');
98:     try {
99:       const stat = await lstat(parent);
100:       if (!stat.isDirectory() || stat.isSymbolicLink()) throw new RemediationError('Destination parent is not a real directory');
101:     } catch (error) {
102:       if ((error as NodeJS.ErrnoException).code === 'ENOENT') return 'directory-missing';
103:       throw error;
104:     }
105:   }
106:   try {
107:     await lstat(absolute);
108:     throw new RemediationError(`Refusing to overwrite existing destination: ${path}`);
109:   } catch (error) {
110:     if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
111:   }
112:   return 'absent';
113: }
114: 
115: /** Caller supplies an identifier from a reviewed dry run. No writes occur for a stale plan. */
116: export async function applyRemediation(repositoryRoot: string, reviewedPlanId: string): Promise<FixOutcome> {
117:   if (!/^[a-f0-9]{64}$/.test(reviewedPlanId)) throw new RemediationError('An exact 64-character reviewed plan ID is required');
118:   const root = await realpath(resolve(repositoryRoot));
119:   const plan = await planRemediation(root);
120:   if (plan.planId !== reviewedPlanId) throw new RemediationError('Stale plan: rerun preview and review the new changes');
121:   // Preflight every path before making *any* change. All paths are a fixed allowlist.
122:   for (const change of plan.proposals) {
123:     if (!FIXES.some((fix) => fix.path === change.path && fix.ruleId === change.ruleId && fix.content === change.content)) {
124:       throw new RemediationError('Unrecognized fix destination or content');
125:     }
126:     await inspectDestination(root, change.path);
127:   }
128:   const changed: string[] = [];
129:   for (const change of plan.proposals) {
130:     const path = safePath(root, change.path);
131:     const parent = dirname(path);
132:     let createdParent = false;
133:     if (parent !== root) {
134:       try {
135:         await mkdir(parent);
136:         createdParent = true;
137:       } catch (error) {
138:         if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error;
139:       }
140:     }
141:     try {
142:       // Recheck the parent after directory creation to reject symlinks.
143:       await inspectDestination(root, change.path);
144:       // Exclusive create + no-follow where supported: never overwrite an existing file.
145:       const flags = constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0);
146:       const handle = await open(path, flags, 0o644);
147:       try { await handle.writeFile(change.content, 'utf8'); }
148:       finally { await handle.close(); }
149:       changed.push(change.path);
150:     } catch (error) {
151:       // Don't remove files from an interrupted write: that could delete data
152:       // changed by another process. Surface the error, never report success.
153:       if (createdParent) { try { await rmdir(parent); } catch { /* may contain data */ } }
154:       throw new RemediationError(`Could not safely create ${change.path}: ${error instanceof Error ? error.message : 'unknown error'}`);
155:     }
156:   }
157:   const final = await runAudit(root);
158:   if (final.errors.length) throw new RemediationError('Audit after applying changes reported an execution error');
159:   const verified = plan.proposals.map((proposal) => ({
160:     ruleId: proposal.ruleId,
161:     status: final.findings.find((item) => item.ruleId === proposal.ruleId)?.status ?? 'UNKNOWN' as const,
162:   }));
163:   if (verified.some((item) => item.status !== 'PASS')) {
164:     throw new RemediationError('A proposed change was written but did not pass verification; inspect the repository');
165:   }
166:   return { schemaVersion: '0.1', mode: 'apply', planId: plan.planId, changed, verified };
167: }
168: 
169: export function renderRemediationMarkdown(result: FixPlan | FixOutcome): string {
170:   if (result.mode === 'apply') {
171:     return ['## RepoTend remediation results', '',
172:       `Created ${result.changed.length} file(s).`, '',
173:       ...result.verified.map((item) => `- ${item.ruleId}: ${item.status}`),
174:       ...(result.changed.length ? ['','Changed: ' + result.changed.join(', ')] : []), ''].join('\n');
175:   }
176:   return ['## RepoTend remediation preview', '',
177:     '**Read-only preview. No files were changed.**', '',
178:     `Plan ID: \`${result.planId}\``, '',
179:     result.proposals.length ? `${result.proposals.length} proposed new file(s):` : 'No supported missing-file fixes are currently needed.', '',
180:     ...result.proposals.flatMap((item) => [`### ${item.path}`, '', item.reason, '', '```diff', item.diff.trimEnd(), '```', '']),
181:     ...(result.proposals.length ? [
182:       'To apply exactly this reviewed plan, run:', '',
183:       `\`node skills/repotend/scripts/remediate.mjs --apply ${result.planId}\``, '',
184:       'This command requires explicit approval and rechecks repository state before writing.', '',
185:     ] : []),
186:   ].join('\n');
187: }

