3: async function main(): Promise<void> {
4:   const { applyRemediation, planRemediation, renderRemediationMarkdown } = await import('./remediation.ts');
5:   let root = process.cwd();
6:   let format: 'json' | 'markdown' = 'markdown';
7:   let apply: string | undefined;
8:   const args = process.argv.slice(2);
9:   for (let i = 0; i < args.length; i++) {
10:     const option = args[i];
11:     if (option === '--root' && args[i + 1]) root = args[++i];
12:     else if (option === '--format' && ['json', 'markdown'].includes(args[i + 1])) format = args[++i] as 'json' | 'markdown';
13:     else if (option === '--apply' && args[i + 1]) apply = args[++i];
14:     else throw new Error(`Unknown or incomplete option: ${option}`);
15:   }
16:   const result = apply ? await applyRemediation(root, apply) : await planRemediation(root);
17:   process.stdout.write(format === 'json' ? JSON.stringify(result, null, 2) + '\n' : renderRemediationMarkdown(result));
18: }
19: main().catch((error: unknown) => {
20:   process.stderr.write(`RepoTend remediation failed: ${error instanceof Error ? error.message : 'unknown error'}\n`);
21:   process.exitCode = 2;
22: });

