6: export type Status = 'PASS' | 'WARN' | 'FAIL' | 'UNKNOWN' | 'NOT_APPLICABLE';
7: export type Severity = 'info' | 'warning' | 'error';
8: export type Confidence = 'verified' | 'heuristic';
9: export type Evidence = { path: string; line?: number };
10: export type Finding = {
11:   ruleId: string; ruleVersion: string; status: Status; severity: Severity;
12:   confidence: Confidence; summary: string; evidence: Evidence[];
13:   recommendation: string | null; enforced: boolean;
14: };
15: export type AuditError = { code: string; ruleId?: string; message: string };
16: export type Report = {
17:   schemaVersion: '0.1'; toolVersion: string; repository: { path: '.' };
18:   mode: 'audit'; profile: 'small-oss'; findings: Finding[]; errors: AuditError[];
19: };
20: export type Observed = {
21:   status: 'PASS' | 'WARN' | 'UNKNOWN' | 'NOT_APPLICABLE'; summary: string;
22:   evidence?: Evidence[]; recommendation?: string | null; confidence?: Confidence;
23: };
24: export type Rule = Readonly<{
25:   id: string; version: string; category: 'conventions' | 'ci' | 'security' | 'dx';
26:   severity: Severity; enforceable: boolean;
27:   check: (reader: RepositoryReader) => Promise<Observed>;
