30: const MAX_FILE_BYTES = 256 * 1024;
31: export type FileProbe =
32:   | { kind: 'present'; size: number }
33:   | { kind: 'missing' }
34:   | { kind: 'unknown'; reason: string };
35: export type ListResult = { kind: 'present'; paths: string[] } | { kind: 'unknown'; reason: string };
36: type InspectResult = { kind: 'present'; isFile: boolean; isDirectory: boolean; size: number } | { kind: 'missing' } | { kind: 'unknown'; reason: string };
37: type ReadResult = { kind: 'present'; text: string } | { kind: 'missing' } | { kind: 'unknown'; reason: string };
38: 
39: export class RepositoryReader {
40:   readonly root: string;
41:   constructor(root: string) { this.root = root; }
42: 
43:   private location(path: string): string {
44:     const full = resolve(this.root, path);
45:     const rel = relative(this.root, full);
46:     if (isAbsolute(rel) || rel === '..' || rel.startsWith('..' + sep) || rel === '') {
47:       throw new Error('Invalid repository-relative path');
48:     }
49:     return full;
50:   }
51: 
52:   private async inspect(path: string): Promise<InspectResult> {
53:     let current = this.root;
54:     try {
55:       for (const part of relative(this.root, this.location(path)).split(sep)) {
56:         current = join(current, part);
57:         const st = await lstat(current);
58:         if (st.isSymbolicLink()) return { kind: 'unknown', reason: 'Symlinked path is not followed' };
59:         if (current === this.location(path)) return { kind: 'present', isFile: st.isFile(), isDirectory: st.isDirectory(), size: st.size };
60:         if (!st.isDirectory()) return { kind: 'unknown', reason: 'Parent is not a directory' };
61:       }
62:     } catch (err) {
63:       if ((err as NodeJS.ErrnoException).code === 'ENOENT') return { kind: 'missing' };
64:       return { kind: 'unknown', reason: 'Cannot inspect path' };
65:     }
66:     return { kind: 'unknown', reason: 'Cannot inspect path' };
67:   }
68: 
69:   async probe(path: string): Promise<FileProbe> {
