171: export async function runAudit(repositoryRoot = process.cwd(), selected: readonly Rule[] = rules): Promise<Report> {
172:   const root = await realpath(resolve(repositoryRoot));
173:   const registry = new Map(selected.map((rule) => [rule.id, rule]));
174:   if (registry.size !== selected.length) throw new Error('Duplicate rule IDs in registry');
175:   const config: Config = await loadConfig(root, new Set(registry.keys()), new Set(selected.filter((r) => r.enforceable).map((r) => r.id)));
176:   const reader = new RepositoryReader(root);
177:   const findings: Finding[] = [];
178:   const errors: AuditError[] = [];
179:   for (const rule of selected) {
180:     const overrides = config.rules[rule.id];
181:     if (overrides?.enabled === false) continue;
182:     try {
183:       const observed = await rule.check(reader);
184:       const enforced = overrides?.enforce === true;
185:       findings.push({
186:         ruleId: rule.id, ruleVersion: rule.version,
187:         status: enforced && observed.status === 'WARN' ? 'FAIL' : observed.status,
188:         severity: rule.severity, confidence: observed.confidence ?? 'verified',
189:         summary: observed.summary, evidence: observed.evidence ?? [],
190:         recommendation: observed.recommendation ?? null, enforced,
191:       });
192:     } catch {
193:       errors.push({ code: 'RULE_EXECUTION', ruleId: rule.id, message: 'Rule execution failed' });
194:       findings.push({ ruleId: rule.id, ruleVersion: rule.version, status: 'UNKNOWN', severity: rule.severity,
195:         confidence: 'verified', summary: 'Rule could not complete', evidence: [], recommendation: null, enforced: false });
196:     }
197:   }
198:   return { schemaVersion: '0.1', toolVersion: '0.1.0-dev', repository: { path: '.' }, mode: 'audit', profile: config.profile, findings, errors };
199: }
