201: function safeTable(value: string): string { return value.replaceAll('|', '\\|').replace(/[\r\n]/g, ' '); }
202: export function renderMarkdown(report: Report): string {
203:   const counts = Object.fromEntries(['PASS', 'WARN', 'FAIL', 'UNKNOWN', 'NOT_APPLICABLE'].map((status) =>
204:     [status, report.findings.filter((f) => f.status === status).length]));
205:   return [
206:     '## RepoTend repository audit (experimental)', '',
207:     '> Checks are advisory unless explicitly enforced. A PASS is not a complete security or quality certification.', '',
208:     `**${counts.PASS} passed · ${counts.WARN} warnings · ${counts.FAIL} enforced failures · ${counts.UNKNOWN} unknown · ${counts.NOT_APPLICABLE} not applicable**`, '',
209:     '| Status | Rule | Observation |', '| --- | --- | --- |',
210:     ...report.findings.map((f) => `| ${f.status} | \`${safeTable(f.ruleId)}\` | ${safeTable(f.summary)} |`),
211:     '', ...report.errors.map((e) => `- ERROR ${safeTable(e.ruleId ?? e.code)}: ${safeTable(e.message)}`),
212:     'See docs/DOGFOODING.md for check limitations.', '',
213:   ].join('\n');
214: }

