13: // This is deliberately a small, documented YAML subset: nested mappings with unquoted
14: // keys and boolean/scalar values. Unsupported YAML is rejected, never silently ignored.
15: export function parseConfig(text: string, knownRules: ReadonlySet<string>, enforceable: ReadonlySet<string>): Config {
16:   const document: Record<string, unknown> = Object.create(null);
17:   const settings: Record<string, RuleSetting> = Object.create(null);
18:   const pending: Record<string, Record<string, boolean>> = Object.create(null);
19:   let insideRules = false;
20:   let currentRule: string | null = null;
21:   let sawSchema = false;
22:   for (const [index, line] of text.replace(/^\uFEFF/, '').split(/\r?\n/).entries()) {
23:     const trimmed = line.trim();
24:     if (!trimmed || trimmed.startsWith('#')) continue;
25:     if (line.includes('\t')) throw new ConfigurationError(`Line ${index + 1}: tabs are not supported`);
26:     const match = /^( *)([A-Za-z0-9_.-]+):(?: *([^#\s][^#]*?) *)?$/.exec(line);
27:     if (!match) throw new ConfigurationError(`Line ${index + 1}: unsupported YAML syntax`);
28:     const indent = match[1].length;
29:     const key = match[2];
30:     const raw = match[3]?.trim();
31:     if (indent === 0) {
32:       insideRules = key === 'rules';
33:       currentRule = null;
34:       if (Object.hasOwn(document, key)) throw new ConfigurationError(`Duplicate top-level key: ${key}`);
35:       if (!['schema', 'profile', 'rules'].includes(key)) throw new ConfigurationError(`Unknown top-level key: ${key}`);
36:       if (insideRules && raw !== undefined) throw new ConfigurationError('rules must contain nested mappings');
37:       if (!insideRules && raw === undefined) throw new ConfigurationError(`${key} requires a value`);
38:       document[key] = raw ?? null;
39:       if (key === 'schema') sawSchema = true;
40:     } else if (indent === 2 && insideRules) {
41:       if (!knownRules.has(key)) throw new ConfigurationError(`Unknown rule ID: ${key}`);
42:       if (Object.hasOwn(pending, key)) throw new ConfigurationError(`Duplicate rule ID: ${key}`);
43:       if (raw !== undefined) throw new ConfigurationError(`Rule ${key} requires a mapping`);
44:       pending[key] = Object.create(null);
45:       currentRule = key;
46:     } else if (indent === 4 && insideRules && currentRule !== null) {
47:       if (!['enabled', 'enforce'].includes(key)) throw new ConfigurationError(`Unknown setting ${currentRule}.${key}`);
48:       if (Object.hasOwn(pending[currentRule], key)) throw new ConfigurationError(`Duplicate setting: ${currentRule}.${key}`);
49:       if (raw !== 'true' && raw !== 'false') throw new ConfigurationError(`${currentRule}.${key} must be true or false`);
50:       pending[currentRule][key] = raw === 'true';
51:     } else {
52:       throw new ConfigurationError(`Line ${index + 1}: unexpected indentation or mapping`);
53:     }
54:   }
55:   if (!sawSchema || document.schema !== '1') throw new ConfigurationError('schema: 1 is required');
56:   if (document.profile !== undefined && document.profile !== 'small-oss') throw new ConfigurationError('Only profile: small-oss is supported');
57:   for (const [id, rule] of Object.entries(pending)) {
58:     if (rule.enforce && !enforceable.has(id)) throw new ConfigurationError(`Rule ${id} is heuristic and cannot be enforced`);
59:     if (rule.enabled === false && rule.enforce === true) throw new ConfigurationError(`Rule ${id} cannot be disabled and enforced`);
60:     settings[id] = { enabled: rule.enabled ?? true, enforce: rule.enforce ?? false };
61:   }
62:   return { schema: 1, profile: 'small-oss', rules: settings };
63: }
